/** OpenTunnel variant B: per-user SSH accounts generated by the broker.
 *
 * Live-verified 2026-11-19 (analysis/com.opentunnel.app/61/
 * investigacion-generate-2026-11-19/RESULTS_LIVE_GENERATE_2026-11-19.md):
 * the provider does NOT issue tnl-... credentials. The client invents the
 * pair and the provider only registers/confirms it: the POST response
 * echoes the invented username back in `requests[].username`, one entry
 * per server, with no password and no expiry anywhere. The 7-day expiry
 * is local to the app, not server data.
 *
 * Pedro's decisions (2026-11-19): variant B — each user gets their own
 * account; the Android app sends its device_id (UUID v3 of ANDROID_ID,
 * exactly as the official OpenTunnel app derives it) in the op 12 request
 * and the broker forwards it to the provider. Username `spdecode-` + 6
 * random [a-z0-9]; password `spdecode-` + 6 DIFFERENT random [a-z0-9]
 * (same length by Pedro's explicit choice, only different).
 *
 * This module is pure: no network, no secrets, no logging of credential
 * values. The POST itself lives in server-vpn-provider.mjs (pinnedRequest).
 * The worker never sees this module: enrichment happens BEFORE the worker
 * so rawText==structuredJson parity (c3-gateway.mjs) still holds.
 */
import {randomInt} from "node:crypto";
import {VpnProviderError} from "./server-vpn-provider.mjs";

export const OPENTUNNEL_GENERATE_URL="https://api.roosterkid.com/api/opentunnel/servers/";
export const OPENTUNNEL_CLIENT="OpenTunnel_1.1.1";
const ALPHABET="abcdefghijklmnopqrstuvwxyz0123456789";
const SUFFIX_LENGTH=6;
const MAX_CATALOG_BYTES=8*1024*1024;

/** UUID v3/v4 canonical lowercase form, as the Android app sends it. */
export function isValidOpentunnelDeviceId(value){
  return typeof value==="string" &&
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(value);
}

function randomSuffix(){
  let out="";
  for(let i=0;i<SUFFIX_LENGTH;i++)out+=ALPHABET[randomInt(ALPHABET.length)];
  return out;
}

/** Pedro's exact format. The two suffixes must differ: if they matched,
 * anyone seeing the username would know the password. */
export function inventOpentunnelCredentials(){
  const userSuffix=randomSuffix();
  let passSuffix=randomSuffix();
  while(passSuffix===userSuffix)passSuffix=randomSuffix();
  const username=`spdecode-${userSuffix}`;
  const password=`spdecode-${passSuffix}`;
  if(username.length!==15||password.length!==15)throw new VpnProviderError("REMOTE_RESPONSE_INVALID");
  return {username,password};
}

/** Exact body the official app sends (same key order, same client string). */
export function buildGenerateBody(deviceId,credentials){
  if(!isValidOpentunnelDeviceId(deviceId))throw new VpnProviderError("INVALID_REQUEST");
  if(!credentials||typeof credentials.username!=="string"||!credentials.username||
     typeof credentials.password!=="string"||!credentials.password)
    throw new VpnProviderError("REMOTE_RESPONSE_INVALID");
  return {action:"generate",username:credentials.username,password:credentials.password,
    client:OPENTUNNEL_CLIENT,device_id:deviceId};
}

function isNonEmptyString(value){return typeof value==="string"&&value.length>0;}

/** Merge a generate response into the public catalog document.
 * The server confirms the invented pair per server: `requests` carries one
 * entry per server with the echoed username. The password never comes back
 * in the response, so the invented password IS the credential (the app's
 * own parser falls back to the stored password the same way).
 * A malformed generate response never throws here: servers without a
 * matching entry are marked credentialsMissing and served without
 * credentials, so one bad entry cannot take down the whole catalog. */
export function mergeOpentunnelGenerateResult(doc,generateText,credentials){
  if(!doc||typeof doc!=="object"||Array.isArray(doc)||!Array.isArray(doc.servers))
    throw new VpnProviderError("REMOTE_RESPONSE_INVALID");
  let response=null;
  try{response=JSON.parse(generateText);}catch{}
  const requests=Array.isArray(response?.requests)?response.requests:[];
  const byHostname=new Map();
  for(const entry of requests){
    if(entry&&typeof entry==="object"&&isNonEmptyString(entry.hostname)&&
       !byHostname.has(entry.hostname))byHostname.set(entry.hostname,entry);
  }
  const servers=doc.servers.map(server=>{
    if(!server||typeof server!=="object"||!isNonEmptyString(server.hostname))
      return {...server,credentialsMissing:true};
    const entry=byHostname.get(server.hostname);
    // The server echoes the invented username; if it ever returned a
    // different one, the returned value is what it registered, so it wins.
    const username=isNonEmptyString(entry?.username)?entry.username:credentials.username;
    if(!entry)return {...server,credentialsMissing:true};
    return {...server,sshUser:username,sshPass:credentials.password};
  });
  return {...doc,servers};
}

/** Every server without credentials, explicitly marked (generate failed). */
export function markOpentunnelCredentialsMissing(doc){
  if(!doc||typeof doc!=="object"||Array.isArray(doc)||!Array.isArray(doc.servers))
    throw new VpnProviderError("REMOTE_RESPONSE_INVALID");
  return {...doc,servers:doc.servers.map(server=>({...server,credentialsMissing:true}))};
}

/** Serialize the (possibly enriched) catalog for the worker. The public
 * count is preserved: generate never adds or removes servers. */
export function packOpentunnelCatalog(doc){
  if(!doc||typeof doc!=="object"||Array.isArray(doc)||!Array.isArray(doc.servers)||
     !Number.isSafeInteger(doc.count)||doc.count!==doc.servers.length||
     doc.status!==200)throw new VpnProviderError("REMOTE_RESPONSE_INVALID");
  const bytes=Buffer.from(JSON.stringify(doc),"utf8");
  if(!bytes.length||bytes.length>MAX_CATALOG_BYTES)throw new VpnProviderError("REMOTE_TOO_LARGE");
  return bytes;
}
